local displaylink = {}
local linkedIcons = {}

local function CacheDisplayIDs()
    WorldDBQueryAsync("SELECT entry, displayid FROM item_template WHERE displayid > 0",
        function(result)
            if result then
                repeat
                    local itemId = result:GetUInt32(0)
                    local displayId = result:GetUInt32(1)
                    displaylink[itemId] = displayId
                until not result:NextRow()
                print("Cached " .. #displaylink .. " item display IDs.")
                for itemId, displayId in pairs(displaylink) do
                    linkedIcons[itemId] = itemIconCache[displayId] or "Interface/ICONS/INV_Misc_QuestionMark"
                end
            else
                print("No results found or an error occurred.")
            end
        end
    )
end

